// held up by a write synchronizing to disk. Scanning a closed store returns
// an error wrapping fs.ErrClosed.
func (s *Store) Scan(r Range, limit int) ([]KVPair, error) {
	if s.closed.Load() {
		return nil, errStoreClosed
	}
