560	// by a later compaction of the backed-up store.
561	//
562	// The ring is streamed in bounded chunks and installed all-or-nothing under
563	// a staging name: a kill at any instant leaves the chain exactly as it was
564	// (staging debris is swept at the next export into, or Open of, the
565	// directory), and the backed-up store is never modified.
566	//
567	// A chain directory that is missing, not a directory, incomplete or damaged
568	// (a missing ring, a broken link, a non-continuous watermark, truncation,
569	// checksum failure or unknown version), or a chain advanced concurrently
570	// during the export, rejects the whole operation with an error wrapping
571	// fs.ErrInvalid and leaves no partial ring. BackupIncremental on a closed
572	// store returns an error wrapping fs.ErrClosed.
573	func (s *Store) BackupIncremental(chainDir string) error {
574		if s.closed.Load() {
575			return errStoreClosed
576		}
577		if chainDir == "" {
578			return errBadBackup
579		}
580		info, err := os.Stat(chainDir)
581		if err != nil {
582			if errors.Is(err, os.ErrNotExist) {
583				return errBadBackup
584			}
585			return err
586		}
587		if !info.IsDir() {
588			return errBadBackup
589		}
590		// Clear debris from an export killed mid-run before inspecting the chain.
591		if err := os.RemoveAll(filepath.Join(chainDir, incrStageDir)); err != nil {
592			return err
593		}
594	
595		art, err := validateBackupChain(chainDir)
596		if err != nil {
597			return err
598		}
599		// The chain tip's present-key set is the baseline the touched set is
600		// diffed against. Streamed from immutable artifacts, it needs no lock.
601		prevPresent, err := presentSetAtTip(chainDir, art)
602		if err != nil {
603			return err
604		}
605	
606		// Anchor at one fixed watermark. This is the only moment the export takes
607		// the write lock; entry resolution and streaming run on the immutable
608		// anchored view without it.
609		s.mu.Lock()
610		if s.closed.Load() {
611			s.mu.Unlock()
612			return errStoreClosed
613		}
614		anchor := backupAnchor{
615			view:      s.current.Load(),
616			watermark: s.nextSeq,
617			snaps:     s.snapshots.Load(),
618		}
619		s.mu.Unlock()
620	
621		startWM := art.endWM
622		touched := collectTouchedKeys(anchor.view, prevPresent, startWM, anchor.watermark)
623	
624		index := art.ringCount + 1
625		return writeIncrementalRing(chainDir, ringHeader{
626			index:    index,
627			prevLink: art.tipCRC,
628			startWM:  startWM,
629			endWM:    anchor.watermark,
630			snaps:    anchor.snaps,
631		}, anchor, touched)
632	}
633	
634	// ringHeader carries the fixed fields of a ring being written.
635	type ringHeader struct {
636		index    uint32
637		prevLink uint32
638		startWM  uint64
639		endWM    uint64
640		snaps    uint64
641	}
642	
643	// collectTouchedKeys diffs the anchored view against the present-key set the
644	// chain held at startWM and returns the touched keys' terminal state, sorted
645	// by key. A key present in the chain but absent from the view was deleted and
646	// forgotten by compaction; it still enters the ring as a tombstone, stamped
647	// at the anchor watermark.
648	func collectTouchedKeys(v *view, prevPresent map[string]struct{}, startWM, endWM uint64) []ringEntryKind {
649		var touched []ringEntryKind
650		seen := make(map[string]struct{}, len(prevPresent))
651		v.rangeEach(func(k string, n *node) bool {
