package snapshot

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"testing"
)

func TestSmokeIncremental(t *testing.T) {
	srcDir := tempDir(t)
	s := openStore(t, srcDir)
	if err := s.CommitBatch([]BatchOp{
		{Key: "a", Value: []byte("a1")},
		{Key: "b", Value: []byte("b1")},
		{Key: "c", Value: []byte("c1")},
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Snapshot(); err != nil {
		t.Fatal(err)
	}

	chain := filepath.Join(t.TempDir(), "chain")
	if err := s.Backup(chain); err != nil {
		t.Fatal(err)
	}
	want1 := allPairs(t, s)

	// ring 1: update a, delete b, add d
	if err := s.CommitBatch([]BatchOp{
		{Key: "a", Value: []byte("a2")},
		{Key: "b", Delete: true},
		{Key: "d", Value: []byte("d1")},
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Snapshot(); err != nil {
		t.Fatal(err)
	}
	if err := s.BackupIncremental(chain); err != nil {
		t.Fatalf("incr1: %v", err)
	}
	want2 := allPairs(t, s)

	// compact to drop b tombstone, then delete c (forgotten-by-compaction key)
	if err := s.Compact(); err != nil {
		t.Fatal(err)
	}
	if err := s.Delete("c"); err != nil {
		t.Fatal(err)
	}
	if err := s.Compact(); err != nil {
		t.Fatal(err)
	}
	// ring 2: only c-delete (tombstone synthesized since compaction forgot it), a unchanged
	if err := s.BackupIncremental(chain); err != nil {
		t.Fatalf("incr2: %v", err)
	}
	want3 := allPairs(t, s)

	// empty ring 3 (nothing touched)
	if err := s.BackupIncremental(chain); err != nil {
		t.Fatalf("incr3 empty: %v", err)
	}

	for i, want := range [][]KVPair{want1, want2, want3, want3} {
		target := filepath.Join(t.TempDir(), fmt.Sprintf("r%d", i))
		rs, err := Restore(chain, target)
		if err != nil {
			t.Fatalf("restore at stage %d: %v", i, err)
		}
		_ = rs
		// note: chain keeps growing; restore here always uses full chain, so
		// only the last state is meaningful. This loop just checks no error.
		rs.Close()
	}

	target := filepath.Join(t.TempDir(), "restored")
	rs, err := Restore(chain, target)
	if err != nil {
		t.Fatalf("restore: %v", err)
	}
	assertSamePairs(t, allPairs(t, rs), want3, "tip state live")
	if _, ok, _ := rs.Get("b"); ok {
		t.Fatal("b resurrected")
	}
	if _, ok, _ := rs.Get("c"); ok {
		t.Fatal("c (compaction-forgotten delete) resurrected")
	}
	if got, ok, _ := rs.Get("a"); !ok || string(got) != "a2" {
		t.Fatalf("a=%q ok=%v", got, ok)
	}
	if got, ok, _ := rs.Get("d"); !ok || string(got) != "d1" {
		t.Fatalf("d=%q ok=%v", got, ok)
	}
	if n := rs.Stats().Snapshots; n != 2 {
		t.Fatalf("snaps=%d want 2", n)
	}
	rs.Close()

	s2, err := Open(target)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	assertSamePairs(t, allPairs(t, s2), want3, "tip state reopen")
	if _, ok, _ := s2.Get("c"); ok {
		t.Fatal("c present after reopen")
	}
}

func TestSmokeIncrementalErrors(t *testing.T) {
	s := openStore(t, tempDir(t))
	if err := s.Put("k", []byte("v")); err != nil {
		t.Fatal(err)
	}
	// missing dir
	if err := s.BackupIncremental(filepath.Join(t.TempDir(), "nope")); !errors.Is(err, fs.ErrInvalid) {
		t.Fatalf("missing dir: %v", err)
	}
	// regular file
	f := filepath.Join(t.TempDir(), "afile")
	if err := os.WriteFile(f, []byte("x"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := s.BackupIncremental(f); !errors.Is(err, fs.ErrInvalid) {
		t.Fatalf("file: %v", err)
	}
	// closed store
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	if err := s.BackupIncremental(t.TempDir()); !errors.Is(err, fs.ErrClosed) {
		t.Fatalf("closed: %v", err)
	}
}

