func TestSmokeIncremental(t *testing.T) {
	s := openStore(t, tempDir(t))
	if err := s.CommitBatch([]BatchOp{
		{Key: "a", Value: []byte("a1")},
		{Key: "b", Value: []byte("b1")},
		{Key: "c", Value: []byte("c1")},
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Snapshot(); err != nil {
		t.Fatal(err)
	}

	chain := filepath.Join(t.TempDir(), "chain")
	if err := s.Backup(chain); err != nil {
		t.Fatal(err)
	}
	want1 := allPairs(t, s)
	headOnly := copyDirTree(t, chain)

	// ring 1: update a, delete b, add d
	if err := s.CommitBatch([]BatchOp{
		{Key: "a", Value: []byte("a2")},
		{Key: "b", Delete: true},
		{Key: "d", Value: []byte("d1")},
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Snapshot(); err != nil {
		t.Fatal(err)
	}
	if err := s.BackupIncremental(chain); err != nil {
		t.Fatalf("incr1: %v", err)
	}
	want2 := allPairs(t, s)
	afterRing1 := copyDirTree(t, chain)

	// compact to drop b tombstone, then delete c (forgotten-by-compaction key)
	if err := s.Compact(); err != nil {
		t.Fatal(err)
	}
	if err := s.Delete("c"); err != nil {
		t.Fatal(err)
	}
	if err := s.Compact(); err != nil {
		t.Fatal(err)
	}
	if err := s.BackupIncremental(chain); err != nil {
		t.Fatalf("incr2: %v", err)
	}
	want3 := allPairs(t, s)
	afterRing2 := copyDirTree(t, chain)

	// empty ring 3 (nothing touched)
	if err := s.BackupIncremental(chain); err != nil {
		t.Fatalf("incr3 empty: %v", err)
	}

	stages := []struct {
		dir  string
		want []KVPair
		snap uint64
	}{
		{headOnly, want1, 1},
		{afterRing1, want2, 2},
		{afterRing2, want3, 2},
	}
	for i, st := range stages {
		target := filepath.Join(t.TempDir(), fmt.Sprintf("r%d", i))
		rs, err := Restore(st.dir, target)
		if err != nil {
			t.Fatalf("restore stage %d: %v", i, err)
		}
		assertSamePairs(t, allPairs(t, rs), st.want, fmt.Sprintf("stage %d live", i))
		if n := rs.Stats().Snapshots; n != st.snap {
			t.Fatalf("stage %d snaps=%d want %d", i, n, st.snap)
		}
		rs.Close()
		s2, err := Open(target)
		if err != nil {
			t.Fatal(err)
		}
		assertSamePairs(t, allPairs(t, s2), st.want, fmt.Sprintf("stage %d reopen", i))
		s2.Close()
	}

	target := filepath.Join(t.TempDir(), "restored")
	rs, err := Restore(chain, target)
	if err != nil {
		t.Fatalf("restore tip: %v", err)
	}
	assertSamePairs(t, allPairs(t, rs), want3, "tip state live")
	if _, ok, _ := rs.Get("b"); ok {
		t.Fatal("b resurrected")
	}
	if _, ok, _ := rs.Get("c"); ok {
		t.Fatal("c (compaction-forgotten delete) resurrected")
	}
	if got, ok, _ := rs.Get("a"); !ok || string(got) != "a2" {
		t.Fatalf("a=%q ok=%v", got, ok)
	}
	if got, ok, _ := rs.Get("d"); !ok || string(got) != "d1" {
		t.Fatalf("d=%q ok=%v", got, ok)
	}
	if n := rs.Stats().Snapshots; n != 2 {
		t.Fatalf("snaps=%d want 2", n)
	}
	rs.Close()

	s2, err := Open(target)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	assertSamePairs(t, allPairs(t, s2), want3, "tip state reopen")
	if _, ok, _ := s2.Get("c"); ok {
		t.Fatal("c present after reopen")
	}
}

