			t.Fatal(err)
		}
	}
	chain := filepath.Join(t.TempDir(), "chain")
	if err := s.Backup(chain); err != nil {
		t.Fatal(err)
	}

	stop := make(chan struct{})
	var wg sync.WaitGroup
	// One slow exporter churning large rings.
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
