package snapshot

import (
	"path/filepath"
	"testing"
)

func TestZZEdgeEmptyHead(t *testing.T) {
	s := openStore(t, tempDir(t))
	chain := filepath.Join(t.TempDir(), "chain")
	if err := s.Backup(chain); err != nil { t.Fatal(err) }
	if err := s.Put("x", []byte("1")); err != nil { t.Fatal(err) }
	if err := s.Put("x", []byte("2")); err != nil { t.Fatal(err) }
	if err := s.BackupIncremental(chain); err != nil { t.Fatal(err) }
	rs, err := Restore(chain, filepath.Join(t.TempDir(), "r"))
	if err != nil { t.Fatal(err) }
	if got, ok, _ := rs.Get("x"); !ok || string(got) != "2" { t.Fatalf("got %q %v", got, ok) }
	rs.Close()
}

func TestZZEdgeMaintenance(t *testing.T) {
	s := openStore(t, tempDir(t))
	s.Put("a", []byte("1"))
	chain := filepath.Join(t.TempDir(), "chain")
	s.Backup(chain)
	s.Put("b", []byte("2"))
	s.BackupIncremental(chain)
	rs, err := Restore(chain, filepath.Join(t.TempDir(), "r"))
	if err != nil { t.Fatal(err) }
	if err := rs.Checkpoint(); err != nil { t.Fatal(err) }
	if err := rs.Compact(); err != nil { t.Fatal(err) }
	if err := rs.Put("c", []byte("3")); err != nil { t.Fatal(err) }
	bd2 := filepath.Join(t.TempDir(), "b2")
	if err := rs.Backup(bd2); err != nil { t.Fatal(err) }
	if err := rs.BackupIncremental(bd2); err != nil { t.Fatal(err) }
	rs.Close()
	rs2, err := Restore(bd2, filepath.Join(t.TempDir(), "r2"))
	if err != nil { t.Fatal(err) }
	defer rs2.Close()
	for _, kv := range [][2]string{{"a","1"},{"b","2"},{"c","3"}} {
		if got, ok, _ := rs2.Get(kv[0]); !ok || string(got) != kv[1] { t.Fatalf("%s=%q %v", kv[0], got, ok) }
	}
}
EOF
go test -run 'TestZZEdge' -v . 2>&1 | tail -8; rm ./zz_edge_test.go

